export type ReaderMetadata = Record<string, unknown>;
type Disposable = { dispose(): void };
type PreparedDocument = { response: Promise<Response>; engines: Promise<unknown[]> };
type Adapter = { open(): unknown; render(prepared: unknown): unknown; restore(entry: unknown, generation: number): unknown; dispose(): unknown };
type Capability = ReaderContractCapability;

